  "as_of_day": 30,
  "stocks": [
    {
      "sku": "S1",
      "units": 15,
      "reserve": 0
    },
    {
      "sku": "S2",
      "units": 10,
      "reserve": 0
    },
    {
      "sku": "S3",
      "units": 9,
      "reserve": 0
    }
  ],
  "orders": [
    {
      "id": "O001",
      "sku": "S1",
      "units": 7,
      "lot": 1,
      "priority": 3,
      "due_day": 30,
      "cancelled": false
    },
    {
      "id": "O002",
      "sku": "S2",
      "units": 7,
      "lot": 1,
      "priority": 2,
      "due_day": 30,
      "cancelled": false
    }
  ]
}
